export default function EquipmentShowcase() {
  return (
    <section className="equip-band dark-band">
      <div className="landing">
        <div className="equip-head">
          <span className="tag">ฮาร์ดแวร์ในระบบ</span>
          <h2>อุปกรณ์วัดน้ำ-ไฟ ครบในชุดเดียว</h2>
          <p>ตั้งแต่มิเตอร์ ตู้คอนโทรล ไปจนถึงบอร์ดและเทอร์มินอล — ออกแบบให้ทำงานร่วมกันทั้งระบบ</p>
        </div>
        <div className="equip-grid">
          {ITEMS.map((it) => (
            <div className="equip-item" key={it.name}>
              <div className="equip-svg" dangerouslySetInnerHTML={{ __html: it.svg }} />
              <div className="equip-label">{it.label}</div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
